def seed_classes(session: Any, class_model: type[Any]) -> int:
    """Upsert all generated classes into database.

    Args:
        session: SQLAlchemy session instance.
        class_model: ORM model class (e.g., model.Class).

    Returns:
        Number of processed rows.
    """
    processed: int = 0
    for row in SEED_CLASSES:
        existing: Any | None = session.get(class_model, row["id"])
        if existing is None:
            session.add(class_model(**row))
        else:
            existing.name = row["name"]
            existing.credits = row["credits"]
            existing.requiredOrElectiveCourse = row["requiredOrElectiveCourse"]
            existing.remark = row["remark"]
            existing.teacher = row["teacher"]
            existing.core = row["core"]
            existing.academicYearSemester = row["academicYearSemester"]
        processed += 1

    session.commit()
    return processed
